/** Epígrafe de balance que le toca a una cuenta que no está en la lista. */
function balancePorDefecto(code) {
  const c = String(code || "");
  const first = c.charAt(0);
  if (first === "1") return "PN_V";
  if (first === "2") return "AN_II";
  if (first === "3") return "AC_II";
  if (first === "4") return c < "450" ? "PC_V" : "AC_III";
  if (first === "5") return c < "560" ? "PC_III" : "AC_VII";
  return "";
}

